def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    seen = [[False] * w for _ in range(h)]
    out = [[bg] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or seen[r][c]:
                continue

            # Group touching non-background cells, including any overlaid markers.
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] != bg):
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)

            best = None
            for top in range(r0, r1 + 1):
                for bottom in range(top + 1, r1 + 1):
                    for left in range(c0, c1):
                        for right in range(left + 1, c1 + 1):
                            area = (bottom - top + 1) * (right - left + 1)
                            counts = {}
                            for y in range(top, bottom + 1):
                                for x in range(left, right + 1):
                                    v = grid[y][x]
                                    if v != bg:
                                        counts[v] = counts.get(v, 0) + 1
                            for color, count in counts.items():
                                if count >= 4 and count / area >= 0.60:
                                    candidate = (count, count / area, area,
                                                 top, bottom, left, right, color)
                                    if best is None or candidate[:3] > best[:3]:
                                        best = candidate

            if best:
                _, _, _, top, bottom, left, right, color = best
                for y in range(top, bottom + 1):
                    for x in range(left, right + 1):
                        out[y][x] = color

    return out
